using System.ComponentModel;
using System.Text;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL")
    ?? "gpt-4o-mini-2024-07-18";

// Build the MEAI chat client from the OpenAI provider
var openAiClient = new OpenAIClient(apiKey);
IChatClient chatClient = openAiClient.GetChatClient(modelId).AsIChatClient();

// Create tool instances
var notebook = new Notebook();
var webSearcher = new WebSearcher();

// Register tools via AIFunctionFactory
var tools = new AITool[]
{
    AIFunctionFactory.Create(webSearcher.SearchAsync, "search_web",
        "Searches the web for a query and returns a snippet of results. Use this to find information on a topic."),
    AIFunctionFactory.Create(notebook.AddNote, "add_note",
        "Saves an important finding or fact to the notebook for later reference."),
    AIFunctionFactory.Create(notebook.GetAllNotes, "get_notes",
        "Retrieves all notes saved so far. Use before writing a final summary."),
};

// Build the agent with Microsoft.Agents.AI
var agent = chatClient.AsAIAgent(
    instructions: """
        You are a research agent. When given a topic you must:
        1. Use search_web multiple times with varied queries to gather diverse information.
        2. Use add_note to record each key finding as you go.
        3. After gathering enough information, use get_notes to review your findings.
        4. Produce a well-structured summary with sections and source attributions.
        Be thorough — make at least 3 different searches before summarizing.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and taking notes.",
    tools: tools);

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       🔍  Research Agent  🔍         ║");
Console.WriteLine("╠══════════════════════════════════════╣");
Console.WriteLine("║  Enter a topic to research, or       ║");
Console.WriteLine("║  type 'exit' to quit.                ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("Research topic> ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("exit", StringComparison.OrdinalIgnoreCase))
        break;

    Console.WriteLine();
    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine($"Researching \"{topic}\"...\n");
    Console.ResetColor();

    notebook.Clear();

    try
    {
        var session = await agent.CreateSessionAsync(
            conversationId: Guid.NewGuid().ToString());

        var runOptions = new ChatClientAgentRunOptions
        {
            ChatOptions = new ChatOptions
            {
                Temperature = 0f,
                MaxOutputTokens = 4096,
            },
        };

        var response = await agent.RunAsync(
            $"Research this topic thoroughly: {topic}",
            session,
            runOptions);

        Console.ForegroundColor = ConsoleColor.Green;
        Console.WriteLine("═══ Research Summary ═══\n");
        Console.ResetColor();
        Console.WriteLine(response.Text);
        Console.WriteLine();
    }
    catch (Exception ex)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.WriteLine($"Error: {ex.Message}");
        Console.ResetColor();
    }
}

Console.WriteLine("Goodbye!");

// ── Tool: Web Search ──────────────────────────────────────────────────────────

sealed class WebSearcher
{
    private static readonly HttpClient s_http = new()
    {
        Timeout = TimeSpan.FromSeconds(15),
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
            { "Accept", "text/html" },
        },
    };

    public async Task<string> SearchAsync(
        [Description("The search query to look up on the web")] string query,
        CancellationToken cancellationToken = default)
    {
        Console.ForegroundColor = ConsoleColor.Yellow;
        Console.WriteLine($"  🌐 Searching: \"{query}\"");
        Console.ResetColor();

        try
        {
            // Use Wikipedia API as a reliable, free search source
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://en.wikipedia.org/w/api.php?action=query&list=search&srsearch={encoded}&srlimit=3&format=json&utf8=1";

            var json = await s_http.GetStringAsync(url, cancellationToken);
            var doc = System.Text.Json.JsonDocument.Parse(json);

            var results = new StringBuilder();
            results.AppendLine($"Search results for: {query}\n");

            var searchResults = doc.RootElement
                .GetProperty("query")
                .GetProperty("search");

            int i = 1;
            foreach (var item in searchResults.EnumerateArray())
            {
                var title = item.GetProperty("title").GetString();
                var snippet = StripHtml(
                    item.GetProperty("snippet").GetString() ?? "");
                results.AppendLine($"{i}. **{title}**");
                results.AppendLine($"   {snippet}");
                results.AppendLine($"   Source: https://en.wikipedia.org/wiki/{Uri.EscapeDataString(title ?? "")}");
                results.AppendLine();
                i++;
            }

            if (i == 1)
                results.AppendLine("No results found.");

            return results.ToString();
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    private static string StripHtml(string html) =>
        System.Text.RegularExpressions.Regex.Replace(html, "<[^>]+>", "");
}

// ── Tool: Notebook ────────────────────────────────────────────────────────────

sealed class Notebook
{
    private readonly List<string> _notes = [];

    public string AddNote(
        [Description("The fact, finding, or insight to save")] string note)
    {
        _notes.Add(note);

        Console.ForegroundColor = ConsoleColor.Magenta;
        Console.WriteLine($"  📝 Note #{_notes.Count}: {Truncate(note, 80)}");
        Console.ResetColor();

        return $"Note saved (total: {_notes.Count}).";
    }

    public string GetAllNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        sb.AppendLine($"All saved notes ({_notes.Count}):\n");
        for (int i = 0; i < _notes.Count; i++)
            sb.AppendLine($"  {i + 1}. {_notes[i]}");
        return sb.ToString();
    }

    public void Clear() => _notes.Clear();

    private static string Truncate(string s, int max) =>
        s.Length <= max ? s : s[..(max - 3)] + "...";
}

