 sealed class WebSearcher
 {
     private static readonly HttpClient s_http = new()
     {
         Timeout = TimeSpan.FromSeconds(15),
         DefaultRequestHeaders =
         {
             { "User-Agent", "ResearchAgent/1.0" },
             { "Accept", "text/html" },
         },
     };

     public async Task<string> SearchAsync(
         [Description("The search query to look up on the web")] string query,
         CancellationToken cancellationToken = default)
     {
         Console.ForegroundColor = ConsoleColor.Yellow;
         Console.WriteLine($"  🌐 Searching: \"{query}\"");
         Console.ResetColor();

         try
         {
             // Use Wikipedia API as a reliable, free search source
             var encoded = Uri.EscapeDataString(query);
             var url = $"https://en.wikipedia.org/w/api.php?action=query&list=search&srsearch={encoded}&srlimit=3&format=json&utf8=1";

             var json = await s_http.GetStringAsync(url, cancellationToken);
             var doc = System.Text.Json.JsonDocument.Parse(json);

             var results = new StringBuilder();
             results.AppendLine($"Search results for: {query}\n");

             var searchResults = doc.RootElement
                 .GetProperty("query")
                 .GetProperty("search");

             int i = 1;
             foreach (var item in searchResults.EnumerateArray())
             {
                 var title = item.GetProperty("title").GetString();
                 var snippet = StripHtml(
                     item.GetProperty("snippet").GetString() ?? "");
                 results.AppendLine($"{i}. **{title}**");
                 results.AppendLine($"   {snippet}");
                 results.AppendLine($"   Source: https://en.wikipedia.org/wiki/{Uri.EscapeDataString(title ?? "")}");
                 results.AppendLine();
                 i++;
             }

             if (i == 1)
                 results.AppendLine("No results found.");

             return results.ToString();
         }
         catch (Exception ex)
         {
             return $"Search failed: {ex.Message}";
         }
     }

     private static string StripHtml(string html) =>
         System.Text.RegularExpressions.Regex.Replace(html, "<[^>]+>", "");
 }

