             foreach (var item in searchResults.EnumerateArray())
             {
                 var title = item.GetProperty("title").GetString();
                 var snippet = StripHtml(
                     item.GetProperty("snippet").GetString() ?? "");
                 results.AppendLine($"{i}. **{title}**");
                 results.AppendLine($"   {snippet}");
                 results.AppendLine($"   Source: https://en.wikipedia.org/wiki/{Uri.EscapeDataString(title ?? "")}");
                 results.AppendLine();
                 i++;
             }

             if (i == 1)
                 results.AppendLine("No results found.");

             return results.ToString();
         }
         catch (Exception ex)
         {
             return $"Search failed: {ex.Message}";
         }
     }

     private static string StripHtml(string html) =>
         System.Text.RegularExpressions.Regex.Replace(html, "<[^>]+>", "");
 }

 // ── Tool: Notebook ────────────────────────────────────────────────────────────

 sealed class Notebook
 {
     private readonly List<string> _notes = [];

     public string AddNote(
         [Description("The fact, finding, or insight to save")] string note)
     {
         _notes.Add(note);

         Console.ForegroundColor = ConsoleColor.Magenta;
         Console.WriteLine($"  📝 Note #{_notes.Count}: {Truncate(note, 80)}");
         Console.ResetColor();

         return $"Note saved (total: {_notes.Count}).";
     }

     public string GetAllNotes()
     {
         if (_notes.Count == 0)
             return "No notes saved yet.";

         var sb = new StringBuilder();
         sb.AppendLine($"All saved notes ({_notes.Count}):\n");
         for (int i = 0; i < _notes.Count; i++)
             sb.AppendLine($"  {i + 1}. {_notes[i]}");
         return sb.ToString();
     }

     public void Clear() => _notes.Clear();

     private static string Truncate(string s, int max) =>
         s.Length <= max ? s : s[..(max - 3)] + "...";
 }
